{
  "findings": [
    {
      "check_id": "AVD-AWS-0067",
      "title": "Lambda permission lacks API Gateway source ARN restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "CRITICAL",
      "explanation": "The API Gateway service principal can invoke the Lambda function without being restricted to a specific API Gateway resource. This could permit invocation from API Gateway resources outside the intended API."
    }
  ],
  "patched_code": "variable \"api_gateway_source_arn\" {\n  description = \"ARN of the API Gateway resource permitted to invoke the Lambda function\"\n  type        = string\n}\n\nresource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = var.api_gateway_source_arn\n}\n",
  "fix_summary": "Added a required source ARN input and applied it to the Lambda permission, restricting invocation to the intended API Gateway resource."
}
